UPDATE articles SET
    title = 'جواز سفر سوري لطفل وُلد في تركيا: الترتيب الصحيح للخطوات',
    intro = 'الجواز هو آخر خطوة في سلسلة تبدأ من مديرية النفوس التركية وتنتهي بقيد مدني يُستخرج داخل سورية. وأكثر ما يوقف العائلات ليس نقص ورقة، بل زواج غير مسجَّل في سورية، وبعده مهلة التسعة أشهر التي تضاعف الرسم.',
    details = '<h2>إن لم تقرأ اليوم غير سطرين</h2>
<p>اقرأ هذين: <strong>هل زواجكما مسجَّل في سجلات الأحوال المدنية في سورية؟ وكم مضى على ولادة الطفل؟</strong> هاتان المعلومتان تحدّدان كل ما بعدهما. الزواج غير المسجَّل في سورية يوقف المعاملة من أولها ولا تنفع معه أي ورقة أخرى. وتجاوز تسعة أشهر على الولادة يرفع رسم تسجيلها لدى البعثة من 50 دولاراً أمريكياً إلى 100، وبعد سنة كاملة إلى 150، بحسب جدول رسوم الخدمة المنشور على صفحة تسجيل الولادات في وزارة الخارجية والمغتربين السورية (آخر تحديث 2026-07-27).</p>
<p>وأمر ثالث يوفّر عليك سفرة كاملة: البعثتان السوريتان العاملتان في تركيا بحسب صفحة البعثات الدبلوماسية في الوزارة هما القنصلية العامة في إسطنبول والقنصلية العامة في غازي عنتاب.</p>

<h2>ابدأ من هنا: الجواز هو آخر خطوة وليس أولها</h2>
<p>لن تُصدر البعثة السورية جواز سفر لطفل غير مقيّد في السجل المدني السوري، ولن تُسجَّل ولادته في ذلك السجل ما لم يكن زواج والديه مسجّلاً في سورية أصلاً. لذلك أول ما ينبغي التحقق منه ليس موعد الجواز، بل هل زواجكما مقيَّد في سورية أم لا. من تزوّج في تركيا بعقد لم يُنقل إلى السجل السوري سيتوقف عند هذه النقطة مهما جمع من أوراق، والحل يبدأ بتسجيل الزواج لا بحجز موعد للجواز.</p>
<p><strong>وهنا الفخّ الذي يكلّف عائلات كثيرة سنة ضائعة:</strong> صفحة تسجيل الولادات في الوزارة تجيب صراحة أن ولادة الطفل لا تُسجَّل إلا بعد تسجيل زواج والديه، وأن قرار إثبات النسب الصادر عن محكمة ابتدائية شرعية خارج سورية يُعدّ غير نافذ لهذا الغرض، وأن على أصحاب العلاقة استصدار قرار بإثبات النسب من المحكمة المختصة داخل سورية في مكان قيدهم. أي أن حكماً من محكمة في تركيا لن يفتح لك هذا الباب مهما كان مصدَّقاً ومترجَماً.</p>
<p>المعاملة تسير في ست مراحل بهذا الترتيب: قيد الولادة لدى الجهة التركية، ثم وثيقة الطفل داخل تركيا، ثم تصديق شهادة الولادة، ثم تسجيل الولادة في البعثة السورية، ثم تثبيت الواقعة داخل سورية واستخراج القيد المدني، والجواز بعدها.</p>

<h2>أولاً: قيد الولادة لدى الجهة التركية</h2>
<p>الإبلاغ عن كل مولود حيّ إلزامي خلال ثلاثين يوماً من الولادة داخل تركيا، ويُقدَّم إلى مديرية النفوس (Nüfus Müdürlüğü) أو إلى المشفى الذي جرت فيه الولادة (قانون 5490، المادة 15/1). والمشفى نفسه ملزم بتبليغ مديرية النفوس خلال خمسة أيام عمل (المادة 15/2)، لكن لا تعتمد على ذلك وحده وتحقق بنفسك من أن القيد تمّ.</p>
<p>وإذا جرت الولادة في البيت دون إشراف كادر صحي، يُقدَّم التبليغ إلى مديرية النفوس ببيان شفهي (المادة 15/4). وواجب التبليغ يقع على الولي أو الوصي أو القيّم، وعند غيابهم على الجد أو الجدة أو الإخوة البالغين أو من يكون الطفل عنده (المادة 15/5).</p>
<p>الوثيقة التي ستحتاجها لاحقاً من الجانب التركي هي بيان الولادة متعدد اللغات (Formül A). وبحسب تعميم المديرية العامة للنفوس والجنسية المؤرخ في 30/04/2019، فإن وقائع ولادة الأجانب تُبلَّغ إلى سفارات الدول الأطراف في الاتفاقيات ذات الصلة فقط، أما مواطنو الدول غير الأطراف فلا يُرسَل عنهم أي إشعار، وتنظّم مديرية النفوس البيان متعدد اللغات وتسلّمه لصاحب العلاقة عند طلبه. والتعميم ذاته ينص على أن تغيّرات الأحوال الشخصية لمن هم في وضع اللجوء لا تُبلَّغ إلى دولتهم الأصلية.</p>
<p><strong>الخلاصة العملية: لا أحد سيرسل ورقة طفلك إلى أي جهة نيابة عنك. اطلب البيان بنفسك من مديرية النفوس.</strong></p>

<h2>ثانياً: وثيقة الطفل داخل تركيا</h2>
<h3>إن كانت العائلة تحت الحماية المؤقتة</h3>
<p>تسجيل الأطفال المولودين في تركيا لمن يستفيدون من الحماية المؤقتة يجري في أقرب وقت (لائحة الحماية المؤقتة، المادة 21/3)، ويُمنح الطفل بطاقة الحماية المؤقتة ورقم هوية أجنبي (المادة 22/1 و22/2)، والبطاقة تُنظَّم دون أي رسم (المادة 22/3).</p>
<p>وأما كيف تُنجَز عملياً فتجيب عنه رئاسة إدارة الهجرة على <a href="https://www.goc.gov.tr/gecici-koruma-sss">صفحة الأسئلة الشائعة للحماية المؤقتة</a>: تؤخذ أولاً وثيقة الولادة من المشفى، وإن كانت الولادة قد جرت خارج المشفى في البيت أو غيره فتؤخذ من المختار (Muhtarlık) وثيقة تفيد بحصول الولادة. وبعد الحصول على إحدى الوثيقتين يُسجَّل الطفل لدى النفوس ومركز التسجيل. والوثائق المطلوبة عند الإنجاز هي وثيقة ولادة الطفل وبطاقتا الحماية المؤقتة للوالدين معاً.</p>
<p>وأنت ملزم فوق ذلك بتبليغ الولادة خلال عشرين يوم عمل (المادة 33/2 فقرة د). والمادة لا تسمّي الجهة في نصّ الفقرة نفسها، لكن الولايات هي التي تصدر بطاقة الحماية المؤقتة (المادة 22/1)، والبلاغات تُقدَّم بالشكل والمدد التي تحددها الولايات (المادة 33/2 فقرة ب)، وإدارة الهجرة توجّه أصحاب الحماية المؤقتة إلى مديرية الهجرة في الولاية التي يقيمون فيها (İl Göç İdaresi Müdürlüğü)، ولإسطنبول مركزا تنسيق منفصلان هما كومكابي وسلطان بيلي. <strong>انتبه: هاتان مهلتان مختلفتان لا مهلة واحدة</strong> — ثلاثون يوماً لمديرية النفوس، وعشرون يوم عمل لمديرية الهجرة، وعشرون يوم عمل تعني نحو أربعة أسابيع، أي أنها تنقضي أبكر في الغالب. عامِلها على أنها الأسبق وأنجز الاثنتين معاً في الشهر الأول.</p>

<h3>إن كان الوالدان يحملان إقامة</h3>
<p>القاعدة هنا مختلفة تماماً، والجملة الأولى من النص هي الأهم: الطفل الأجنبي المولود في تركيا يبقى فيها بشهادة ولادته، تبعاً لمدة إقامة أمه أو أبيه، <strong>إلى أن تُنظَّم له وثيقة سفر ويُقدَّم طلب الإقامة</strong>. وشهادة الولادة وحدها لا تمنح حق الدخول إلى تركيا ولا الخروج منها، ويجب استخراج إقامة مناسبة له خلال مئة وثمانين يوماً، وتُنظَّم الإقامة سارية من تاريخ الولادة (لائحة تطبيق القانون 6458، المادة 21/13). ومن لم يراجع خلال هذه المدة يُحصَّل منه الرسم مضاعفاً عند الخروج، وإذا دُفع هذا الرسم فلا يُطبَّق حظر دخول مؤقت.</p>
<p>اقرأ هذه الجملة مرة أخرى: <strong>الجواز ومهلة المئة والثمانين يوماً ليسا موضوعين منفصلين، بل موعد واحد.</strong> وثيقة الولادة تغطّي الطفل إلى أن تصير في يدك وثيقة سفره وتُقدِّم طلب الإقامة، ووثيقة السفر هذه هي الجواز السوري في حالتنا. فإن كنت تحمل إقامة، لا تؤجل سلسلة التسجيل هذه إلى ما بعد الولادة بشهور، لأن العدّاد يعمل منذ يوم الولادة.</p>

<h2>ثالثاً: تصديق شهادة الولادة قبل الذهاب إلى البعثة</h2>
<p>تشترط وزارة الخارجية والمغتربين السورية أن تُقدَّم شهادة الولادة الرسمية الصادرة عن سلطات بلد الولادة مرفقة بترجمتها، وأن تكون الوثيقتان معاً مصدَّقتين أصولاً من وزارة خارجية البلد المعني، أي وزارة الخارجية التركية.</p>
<p>وهنا خطأ مكلف يقع فيه كثيرون: سوريا ليست طرفاً في اتفاقية الأبوستيل، ووزارة الخارجية التركية تنص صراحة على أن الورقة التي حصلت على أبوستيل لا تستطيع الوزارة تصديقها بعد ذلك. فلا تسلك الطريقين معاً، ولا تدفع مقابل أبوستيل قبل أن تسأل البعثة أي تصديق تقبله.</p>
<p>المسار الذي تنشره وحدة التصديق في وزارة الخارجية التركية للوثائق التي لن تُختم بالأبوستيل:</p>
<ol>
<li>استلام الوثيقة من الجهة المختصة، أي مديرية النفوس.</li>
<li>ترجمتها إلى اللغة المطلوبة عند طلب ذلك.</li>
<li>تصديق الترجمة لدى كاتب العدل (Noter).</li>
<li>تصديقها لدى الولاية أو القائممقامية (Valilik / Kaymakamlık) في المكان الذي نُظّمت فيه الوثيقة.</li>
<li>تصديقها أخيراً لدى وحدة التصديق في وزارة الخارجية التركية، وهي تعمل بموعد مسبق يُحجز عبر <a href="https://tasdik.mfa.gov.tr">موقع التصديق الرسمي</a>.</li>
</ol>
<p><strong>ولا تتوقف هنا.</strong> ختم الخارجية التركية ليس نهاية السلسلة بل شرط دخولها: البعثة السورية تقدّم خدمة مستقلة اسمها <a href="https://mofaex.gov.sy/services/%D8%AA%D8%B5%D8%AF%D9%8A%D9%82-%D8%A7%D9%84%D9%88%D8%AB%D8%A7%D8%A6%D9%82-%D9%81%D9%8A-%D8%A7%D9%84%D8%A8%D8%B9%D8%AB%D8%A7%D8%AA-%D8%A7%D9%84%D8%AF%D8%A8%D9%84%D9%88%D9%85%D8%A7%D8%B3%D9%8A%D8%A9-%D9%84%D9%84%D9%88%D8%AB%D8%A7%D8%A6%D9%82-%D8%A7%D9%84%D8%B5%D8%A7%D8%AF%D8%B1%D8%A9-%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%84%D8%AF-%D8%A7%D9%84%D9%85%D8%B6%D9%8A%D9%81">تصديق الوثائق الصادرة من البلد المضيف</a>، وشرطها المعلن أن تكون الوثيقة أصلية وصادرة من بلد البعثة ومصادقاً عليها من وزارة خارجية البلد المضيف. وصفحة الخدمة تنص كذلك على أن الترجمة لا يجوز تصديقها إلا بعد تصديق الوثيقة نفسها واستيفاء الرسوم، أي أن الورقة وترجمتها تُعامَلان معاملتين. وفيها خبر جيد للعائلات التي لا يستطيع صاحب العلاقة فيها الحضور: شرط أن يكون مقدّم المعاملة صاحب العلاقة أو أحد أقاربه حتى الدرجة الرابعة أو وكيله القانوني <strong>تُستثنى منه وثائق الأحوال المدنية</strong>.</p>
<p>وجدول رسوم صفحة تسجيل الولادات يدرج بنداً مستقلاً باسم تصديق شهادة الميلاد الأجنبية بمقدار 50 دولاراً أمريكياً (آخر تحديث 2026-07-27). احسبه ضمن ميزانيتك، واسأل عند الشباك أي البنود ينطبق على ملفك أنت.</p>

<h2>رابعاً: تسجيل الولادة في البعثة السورية</h2>
<p>الوثائق التي تعلنها <a href="https://mofaex.gov.sy/services/%D8%A3%D8%AD%D9%88%D8%A7%D9%84-%D9%85%D8%AF%D9%86%D9%8A%D8%A9-%D8%AA%D8%B3%D8%AC%D9%8A%D9%84-%D8%A7%D9%84%D9%88%D9%84%D8%A7%D8%AF%D8%A7%D8%AA">وزارة الخارجية والمغتربين</a> لتسجيل واقعة الولادة:</p>
<ul>
<li>شهادة الولادة التركية مرفقة بترجمتها ومصدَّقة من وزارة الخارجية.</li>
<li>بطاقة عائلية أو بيان قيد عائلي أو أي وثيقة رسمية تثبت أن الزواج قد سُجّل في سجلات الأحوال المدنية في سورية.</li>
<li>صور البطاقات الشخصية أو جوازات السفر للوالدين، أو إخراجات قيد فردية حديثة لم يمضِ على استخراجها أكثر من ستة أشهر.</li>
</ul>
<p>ويُشترط حضور الأب شخصياً أو الوصي الشرعي. وإن كان الأب غائباً فصفحة الخدمة تجيب أن واجب التبليغ عن واقعات الولادة يعود على الوالد، وفي حال غيابه ينتقل إلى الوالدة أو إلى أقرباء المولود البالغين.</p>
<p><strong>الرسوم، وهي المهلة الحقيقية الوحيدة في الجانب السوري.</strong> جدول رسوم الخدمة على الصفحة نفسها (آخر تحديث 2026-07-27) يربط الكلفة بعمر الواقعة لا بشيء آخر:</p>
<ul>
<li>تثبيت الواقعة لدى البعثة قبل مضي تسعة أشهر على حدوثها: 50 دولاراً أمريكياً.</li>
<li>بعد تسعة أشهر ودون السنة الميلادية: 100 دولار، وهي 50 دولاراً رسماً أصلياً و50 دولاراً غرامة.</li>
<li>بعد تجاوز السنة الكاملة: 150 دولاراً، وهي 50 دولاراً رسماً أصلياً و100 دولار غرامة.</li>
<li>تصديق شهادة الميلاد الأجنبية: 50 دولاراً أمريكياً.</li>
</ul>
<p>ويُدفع ما يعادلها باليورو في بعثات منطقة اليورو، وتشترط الوزارة أن يكون الدولار من إصدار 2017 أو أحدث. والرسوم قابلة للتغيير، فراجع الصفحة قبل الذهاب.</p>
<p>ومدة الإنجاز المعلنة على الصفحة هي من 15 إلى 25 دقيقة مع مراعاة ضغط العمل في صالة التصديقات، وطريقة التقديم حضورية، والصفحة لا تشترط حضور صاحب العلاقة نفسه في هذه الخدمة. وإجراء الخدمة أربع خطوات: حجز الدور عبر تطبيق المواعيد الرسمي (MOFA SY)، ثم التقدم بالطلب في الموعد مع الأوراق الثبوتية، ثم تسديد الرسوم، ثم استلام نسخة من بيان الولادة عليها لصاقة التصديق الإلكترونية.</p>
<p>وهناك حدّ زمني صريح، لكنه ليس باباً مغلقاً كما يُشاع: لا تُسجَّل لدى البعثات الدبلوماسية واقعات الولادة التي مرّ عليها 18 سنة، <strong>ولكن الوزارة تضيف أنه يمكن عبر البعثة البدء بإجراءات تسجيل من تجاوزوا الثامنة عشرة، وتُستكمل باقي الإجراءات في سورية.</strong> فإن كان ابنك قد تجاوز الثامنة عشرة فلا تيأس ولا تصدّق من يقول لك إن الطريق انسدّ، بل اسأل البعثة عن إجراءات البدء.</p>

<h2>خامساً: تثبيت الولادة داخل سورية واستخراج القيد المدني</h2>
<p><strong>هذه هي المرحلة التي يسقط فيها أكثر الملفات، لأن أحداً لا يخبر بها الأهل.</strong> بيان الولادة الذي استلمته من البعثة ليس قيداً في السجل المدني، بل ورقة تُرسَل إلى سورية ليُقيَّد الطفل هناك. وصفحة الجواز في الوزارة تجيب صراحة عن سؤال إصدار جواز لطفل حديث الولادة بأن التسلسل هو: تصديق شهادة الميلاد من وزارة خارجية بلد الإقامة، ثم تسجيل الواقعة في السفارة السورية، ثم إرسال بيان الولادة الصادر عن السفارة إلى سورية لتسجيل الولادة واستخراج قيد مدني فردي عليه صورة شخصية، <strong>وبعد الحصول على القيد المدني فقط يمكن التقدم بطلب استخراج جواز سفر من البعثة.</strong></p>
<p>وصفحة تسجيل الولادات تشرح كيف يتمّ ذلك داخل سورية في خطوتين: تصديق بيان الولادة الممنوح في البعثة لدى الإدارة القنصلية أو أحد مكاتبها في المحافظات، ثم مراجعة دائرة الأحوال المدنية لتثبيت الواقعة بعد إبراز البيان.</p>
<p>ومن يستطيع القيام بذلك ولم يعد له أحد في البلد؟ الصفحة نفسها تجيب: يمكن لأقرباء الوالدين حتى الدرجة الرابعة، أو لوكيلهما القانوني، تثبيت الواقعة في سورية. أي أن ابن العم أو الخال أو وكيلاً بموجب وكالة تُنظَّم لدى البعثة يستطيع إنهاءها نيابةً عنكما. <strong>لا تحجز موعد الجواز قبل أن يصلك خبر صدور القيد المدني الفردي للطفل، لأنك ستُردّ من الشباك بغير ورقة.</strong></p>

<h2>سادساً: طلب الجواز</h2>
<p>بعد أن يصبح الطفل مقيّداً في السجل المدني يمكن التقدم بطلب <a href="https://mofaex.gov.sy/services/%D8%A5%D8%B5%D8%AF%D8%A7%D8%B1-%D8%AC%D9%88%D8%A7%D8%B2-%D8%B3%D9%81%D8%B1-%D9%84%D8%A3%D9%88%D9%84-%D9%85%D8%B1%D8%A9">جواز سفر لأول مرة</a>:</p>
<ol>
<li>احجز الدور عبر تطبيق المواعيد الرسمي (MOFA SY).</li>
<li>اطبع استمارة الجواز من التطبيق، والطباعة يجب أن تكون بالألوان.</li>
<li>احضر في الموعد المحدد ومعك صورة حجز الموعد، وإخراج قيد فردي للطفل لا يتجاوز تاريخ استخراجه ستة أشهر، يتضمن صورة شخصية حديثة، على أن تكون الصورة مصدَّقة من مختار المنطقة ومُعرَّفة بموجب شاهد من أهل المنطقة ومصدَّقة أصولاً من وزارة الخارجية والمغتربين السورية، وصورتان شخصيتان ملونتان بخلفية بيضاء <strong>وملابس داكنة</strong> قياس 4×4، وبطاقة إقامة البلد المضيف مع صورة عنها.</li>
<li>سدّد الرسوم.</li>
</ol>
<p><strong>الرسوم.</strong> جدول رسوم الخدمة على صفحة الوزارة (آخر تحديث 2026-03-29): جواز السفر بالدور العادي 200 دولار أمريكي، وبالدور المستعجل 400 دولار أمريكي، وما يعادلهما بالعملة الأوروبية الموحدة في بعثات منطقة اليورو، ويجب أن يكون الدولار من إصدار 2017 أو أحدث. راجع الصفحة قبل الموعد لأن الرسوم قابلة للتعديل.</p>
<p><strong>خذ الطفل معك.</strong> صفحة الخدمة تسجّل طريقة التقديم على أنها حضورية وتضع خانة صاحب العلاقة على «نعم»، وتذكر ضمن إجراء الخدمة أخذ توقيع وبصمة صاحب العلاقة الإلكترونيين على منظومة الجوازات. وتنص كذلك على أن أخذ بصمة الأصابع إلزامي لصاحب الجواز الذي يتراوح عمره بين 15 و70 عاماً. لا تفترض من هذا أن الطفل يمكن أن يبقى في البيت، واسأل البعثة عند الحجز إن كان في الأمر استثناء لعمره.</p>
<p>والشرط الذي يوقف كثيراً من الأمهات هو التالي: القاصر دون الثامنة عشرة يلزمه حضور الأب أو الجد لجهة الأب مع إبراز صورة عن جواز سفره. وإذا كانت الأم هي مقدّمة الطلب فعليها إبراز وصاية شرعية صادرة عن القاضي الشرعي في سورية ومصدّقة من وزارة الخارجية السورية لم يمضِ على استخراجها أكثر من ثلاثة أشهر، أو أخذ موافقة الولي الشرعي، والوزارة تحدد الولي الشرعي هنا بالأب والجد لجهة الأب. وإن كان الأب متوفى أو مسافراً يحق للعم أو الأخ استخراج الجواز للقاصر بعد إبراز الثبوتيات والتدقيق أصولاً.</p>

<h2>أين تراجع: إسطنبول أو غازي عنتاب</h2>
<p>تدرج <a href="https://mofaex.gov.sy/diplomatic-missions">صفحة البعثات الدبلوماسية</a> في وزارة الخارجية والمغتربين بعثتين سوريتين في تركيا: القنصلية العامة في إسطنبول، والقنصلية العامة في غازي عنتاب. ولأن العناوين وأرقام الهاتف تتبدّل، خذها من صفحة البعثات نفسها لا من منشور في مجموعة أو موقع غير رسمي، وتأكد قبل السفر أي بعثة تخدم ولايتك.</p>
<p>وننشر على الموقع دليلين قد يوفّران عليك وقتاً: <a href="/article/syrian-consulate-gaziantep-guide">القنصلية السورية في غازي عنتاب: العنوان وحجز الموعد</a> و<a href="/article/syrian-consulate-appointment">حجز موعد القنصلية السورية في إسطنبول</a>، ودليل <a href="/article/syrian-passport-renewal">رسوم جواز السفر السوري</a> لمن يريد التفاصيل المالية وحدها.</p>

<h2>وإن كان الزواج غير مسجَّل: من أين تبدأ</h2>
<p>البعثة تقدّم خدمة <a href="https://mofaex.gov.sy/services/%D8%A3%D8%AD%D9%88%D8%A7%D9%84-%D9%85%D8%AF%D9%86%D9%8A%D8%A9-%D8%AA%D8%B3%D8%AC%D9%8A%D9%84-%D8%A7%D9%84%D8%B2%D9%88%D8%A7%D8%AC">تسجيل الزواج</a> للسوريين الذين تزوّجوا خارج سورية. والوثائق المعلنة: عقد زواج مبرم أصولاً لدى الدوائر الشرعية المختصة المعترف بها في دولة الإقامة ومصدَّق من وزارة الخارجية في الدولة المضيفة، وصورتان عن بيان قيد فردي حديث للزوجة إن كانت سورية مصادَق من وزارة الخارجية والمغتربين السورية لم يمضِ عليه أكثر من ستة أشهر، وصورة عن هوية الزوج أو جواز سفره أو إخراج قيد حديث، وصورة عن هوية الزوجة أو جواز سفرها. ويُشترط حضور الزوج شخصياً إذا كان سورياً، أو الزوجة السورية إن لم يكن الزوج سورياً.</p>
<p>ورسوم هذه الخدمة تتبع السلّم الزمني نفسه: 50 دولاراً قبل مضي تسعة أشهر على الواقعة، و100 دولار بعد تسعة أشهر ودون السنة، و150 دولاراً بعد سنة كاملة، إضافة إلى 50 دولاراً لتصديق عقد الزواج. وتذكّر ما قلناه في الأعلى: قرار إثبات نسب من محكمة خارج سورية لا يُغني عن هذا، والقرار يجب أن يصدر عن المحكمة المختصة داخل سورية في مكان قيدكم.</p>
<p><strong>ولا تنتهي معاملة الزواج عند شباك البعثة.</strong> التعليمات العامة على صفحة الخدمة نفسها تنص على أن البعثة الدبلوماسية لا تقوم بتسجيل الزواج في الدول الأجنبية، وأن على الزوجين توكيل شخصين في سورية ليتم تسجيل الزواج أصولاً هناك. وتثبيت واقعة الزواج داخل سورية يتم بخطوتين تنشرهما الصفحة ذاتها: تصديق بيان الزواج الممنوح في البعثة لدى الإدارة القنصلية أو أحد مكاتبها في المحافظات، ثم مراجعة دائرة الأحوال المدنية لتثبيت الواقعة بالبيان المذكور. وانتبه إلى فرق دقيق عن الولادة: صفحة الولادة تسمح بأن يثبّت الواقعة أقرباء الوالدين حتى الدرجة الرابعة أو وكيلهما القانوني، أما صفحة الزواج فتنص على توكيل شخصين، فلا تنقل قاعدة الولادة إلى الزواج، واسأل البعثة عن تنظيم الوكالة في الزيارة نفسها حتى لا تضطر إلى العودة.</p>

<h2>لا تتعامل مع وسيط</h2>
<p>وزارة الخارجية والمغتربين تنبّه على منصتها الإلكترونية إلى عدم التعامل مع أي سمسار أو وسيط، وأن التطبيق مخصص لخدمة المواطنين مباشرة دون حاجة إلى طرف ثالث، وأن الخدمات تُقدَّم حصرياً عبر منصتها الرسمية. ومن يطلب منك مالاً مقابل تأمين موعد يبيعك شيئاً لا يملكه.</p>

<h2>ما يختلف بحسب الولاية وما لم نستطع تأكيده</h2>
<ul>
<li><strong>الرسوم التركية.</strong> لم نطبع رقماً لرسم تصديق وزارة الخارجية التركية ولا لأجر كاتب العدل ولا لختم الولاية أو القائممقامية. الرقم الوارد في تعرفة قانون الرسوم 492 لم نستطع تثبيت مطابقته بثقة كافية، ولم نتحقق كذلك هل يُحتسب الرسم عن كل وثيقة أم عن المجموعة، وهل تُحتسب الترجمة وثيقة ثانية. اسأل عن المبلغ في مكان الدفع نفسه.</li>
<li><strong>مدة إصدار الجواز.</strong> خانة مدة الإنجاز على صفحة الجواز فارغة. النسخة السابقة من صفحتنا كانت تذكر مدة من شهر إلى ثلاثة أشهر بلا مصدر رسمي، فحُذفت. والوزارة كانت قد نشرت مدداً في نسخة سابقة من صفحتها ثم أزالتها، فلا تعتمد على أي رقم متداول.</li>
<li><strong>هل تُقبل بطاقة الحماية المؤقتة مكان بطاقة إقامة البلد المضيف؟</strong> لم نجد نصاً رسمياً يجيب عن ذلك. اسأل البعثة قبل الموعد.</li>
<li><strong>حضور الطفل الرضيع.</strong> الصفحة تضع صاحب العلاقة على «نعم» والتقديم حضورياً، وتحصر البصمة بمن هم بين 15 و70 عاماً. أي أن النصّين لا يحسمان معاً ما يُطلب عملياً من رضيع. خذه معك واسأل.</li>
<li><strong>التصديق.</strong> ما تقبله البعثة قد يختلف عملياً عن المسار المكتوب، وبعض مديريات النفوس تسلّم البيان متعدد اللغات في الحال وبعضها يطلب مراجعة ثانية، وبعضها يطلب المراجعة في المنطقة التي سُجّلت فيها الولادة.</li>
<li><strong>الحماية المؤقتة تختلف بحسب الولاية.</strong> إجراءات مديرية الهجرة (İl Göç İdaresi) ليست واحدة في كل الولايات، ولإسطنبول ترتيب خاص بها عبر مركزي كومكابي وسلطان بيلي. راجع <a href="https://www.goc.gov.tr/gecici-koruma-sss">صفحة الأسئلة الشائعة للحماية المؤقتة</a>.</li>
<li><strong>أي بعثة تخدم ولايتك.</strong> الوزارة تنشر البعثتين ولا تنشر توزيعاً للولايات بينهما ولا حجم المواعيد المتاحة في كل منهما. اسأل قبل أن تحجز وتسافر.</li>
<li><strong>استثناء اللجوء في التعميم التركي.</strong> لم نتمكن من تأكيد ما إذا كان يشمل أصحاب الحماية المؤقتة، لأن الحماية المؤقتة وضع قانوني مستقل عن صفة اللاجئ.</li>
</ul>',
    documents = ARRAY['بيان الولادة متعدد اللغات (Formül A) من مديرية النفوس، مع ترجمته.', 'سلسلة التصديق كاملة: كاتب العدل (Noter)، ثم الولاية أو القائممقامية، ثم وحدة التصديق في الخارجية التركية، ثم البعثة السورية.', 'بطاقة عائلية أو بيان قيد عائلي أو أي وثيقة تثبت أن زواج الوالدين مسجَّل في سورية.', 'هويتا الوالدين أو جوازاهما، أو إخراجا قيد فرديان لم يمضِ على استخراجهما أكثر من ستة أشهر.', 'للجواز: إخراج قيد فردي للطفل لا يتجاوز تاريخ استخراجه ستة أشهر بصورة مصدَّقة من المختار ومُعرَّفة بشاهد ومصدَّقة من الخارجية السورية، وصورتان 4×4 بخلفية بيضاء وملابس داكنة، وبطاقة إقامة البلد المضيف.', 'تحت الحماية المؤقتة: وثيقة ولادة الطفل، وبطاقتا الحماية المؤقتة للوالدين معاً.']::text[],
    steps = ARRAY['تحقّق أولاً: هل زواجكما مسجَّل في السجل المدني في سورية؟ إن لم يكن، ابدأ بتسجيل الزواج قبل أي شيء آخر.', 'بلّغ الولادة لمديرية النفوس التركية خلال ثلاثين يوماً، واطلب بيان الولادة متعدد اللغات (Formül A) بنفسك.', 'صدّق الشهادة وترجمتها: كاتب العدل، ثم الولاية أو القائممقامية، ثم وحدة التصديق في الخارجية التركية بموعد مسبق، ثم البعثة السورية.', 'احجز عبر تطبيق المواعيد الرسمي (MOFA SY) وسجّل الولادة لدى البعثة قبل مضي تسعة أشهر، واستلم بيان الولادة.', 'أرسل البيان إلى سورية: يُصدَّق لدى الإدارة القنصلية أو أحد مكاتبها في المحافظات، ثم تُراجَع دائرة الأحوال المدنية لتثبيت الواقعة واستخراج قيد مدني فردي عليه صورة.', 'بعد صدور القيد المدني فقط، احجز موعد الجواز واحضر ومعك الطفل والولي الشرعي.']::text[],
    tips = ARRAY['الجواز آخر خطوة لا أولها: لا تُقبل معاملة الجواز قبل أن يصير الطفل مقيّداً في السجل المدني داخل سورية.', 'تسعة أشهر هي ما يحدد الكلفة: 50 دولاراً قبلها، و100 دولار بعدها ودون السنة، و150 دولاراً بعد سنة كاملة (صفحة الوزارة، آخر تحديث 2026-07-27).', 'زواج غير مسجَّل في سورية يوقف كل شيء، والبعثة لا تسجّله داخل سورية: يلزم توكيل شخصين هناك، وقرار إثبات نسب من محكمة خارج سورية غير نافذ لهذا الغرض.', 'سوريا ليست طرفاً في اتفاقية الأبوستيل، والخارجية التركية لا تصدّق ورقة خُتمت بالأبوستيل — لا تسلك الطريقين معاً.', 'البعثتان في تركيا بحسب صفحة البعثات في الوزارة: إسطنبول وغازي عنتاب.', 'احجز بنفسك عبر تطبيق المواعيد الرسمي (MOFA SY)؛ الوزارة تنبّه إلى عدم التعامل مع أي سمسار أو وسيط.']::text[],
    warning = 'الجواز آخر خطوة لا أولها: لن تُسجَّل ولادة طفلك ما لم يكن زواجكما مسجَّلاً في سورية، وتأخير تسجيل الولادة لدى البعثة بعد تسعة أشهر يرفع الرسم من 50 دولاراً إلى 100، وبعد سنة كاملة إلى 150.',
    seo_title = 'جواز سفر سوري لطفل وُلد في تركيا: الترتيب الصحيح',
    seo_description = 'طفلك وُلد في تركيا وتريد له جوازاً سورياً؟ سجّل الولادة لدى البعثة قبل تسعة أشهر، ثم ثبّتها في سورية، ثم اطلب الجواز. الترتيب والوثائق والرسوم.',
    last_update = CURRENT_DATE
WHERE slug = 'children-passport-syria';

-- ═══════════════════════════════════════════════════════════════════════
-- التحقق: أطوال المحتوى الجديدة + صفر بقايا محظورة
SELECT slug, length(details) AS details_len, array_length(steps,1) AS steps_n,
       length(seo_title) AS st, length(seo_description) AS sd,
       (details LIKE '%1,966%' OR details LIKE '%444 4 868%')::int AS banned
FROM articles WHERE slug IN ('lost-kimlik-replacement','lost-residence-card',
  'lost-passport-turkey','kimlik-renewal-steps','children-passport-syria')
ORDER BY slug;
